package travel

/** Python 3.11 Unicode mappings generated by tools/generate_unicode.py. */
object PyStr {
    private fun table(name: String): Map<Int, String> =
        requireNotNull(PyStr::class.java.classLoader.getResourceAsStream("unicode/$name.tsv"))
            .bufferedReader(Charsets.UTF_8).useLines { lines ->
                lines.filter { !it.startsWith("#") && it.isNotEmpty() }.associate { line ->
                    val columns = line.split('\t')
                    columns[0].toInt(16) to columns[1].split(' ').joinToString("") { String(Character.toChars(it.toInt(16))) }
                }
            }
    private val lowerTable by lazy { table("lower") }
    private val casefoldTable by lazy { table("casefold") }
    private fun convert(value: String, mapping: Map<Int, String>): String = buildString {
        var i = 0
        while (i < value.length) {
            val cp = value.codePointAt(i)
            append(mapping[cp] ?: String(Character.toChars(cp)))
            i += Character.charCount(cp)
        }
    }
    fun lower(value: String): String = convert(value, lowerTable)
    fun casefold(value: String): String = convert(value, casefoldTable)
}
